; KN_ChanOwner: called with b = channel offset ($00/$10/$20/$30), h = $C8.
; Returns to the caller (b = owning track) only when that track read a new row this
; update and it is not a hold; otherwise pops the caller and returns to the update.
; The SFX track wins whenever it is on, even between its rows.
KN_ChanOwner:
    ld l,b                          ; 7a00 68        set-0 (SFX) track b: active?
    ld a,[hl+]                      ; 7a01 2a      
    cp $00                          ; 7a02 fe 00   
    jp z,KN_ChanOwner.music         ; 7a04 ca 18 7a
    ld a,[hl]                       ; 7a07 7e        not on the row it was read -> nobody writes
    cp $00                          ; 7a08 fe 00   
    jp nz,KN_ChanOwner.none         ; 7a0a c2 34 7a
    ld a,$0a                        ; 7a0d 3e 0a     note byte
    add b                           ; 7a0f 80      
    ld l,a                          ; 7a10 6f      
    ld a,[hl]                       ; 7a11 7e      
    cp $89                          ; 7a12 fe 89     hold -> nobody writes
    jp z,KN_ChanOwner.none          ; 7a14 ca 34 7a
    ret                             ; 7a17 c9        SFX owns the channel
.music
    ld a,b                          ; 7a18 78        SFX track off: try the music track (b += $40)
    add $40                         ; 7a19 c6 40   
    ld b,a                          ; 7a1b 47      
    ld l,a                          ; 7a1c 6f      
    ld a,[hl+]                      ; 7a1d 2a      
    cp $00                          ; 7a1e fe 00   
    jp z,KN_ChanOwner.none          ; 7a20 ca 34 7a
    ld a,[hl]                       ; 7a23 7e      
    cp $00                          ; 7a24 fe 00   
    jp nz,KN_ChanOwner.none         ; 7a26 c2 34 7a
    ld a,$0a                        ; 7a29 3e 0a   
    add b                           ; 7a2b 80      
    ld l,a                          ; 7a2c 6f      
    ld a,[hl]                       ; 7a2d 7e      
    cp $89                          ; 7a2e fe 89   
    jp z,KN_ChanOwner.none          ; 7a30 ca 34 7a
    ret                             ; 7a33 c9        music owns the channel
.none
    pop de                          ; 7a34 d1        drop our return address: the caller returns
    ret                             ; 7a35 c9      

; Channel output: write the owning track to the registers (once per row).
KN_Ch1Out:
    ld h,HIGH(wSfxTracks)           ; 7a36 26 c8   
    call KN_ChanOwner               ; 7a38 cd 00 7a
    ld a,b                          ; 7a3b 78      
    add $07                         ; 7a3c c6 07     NR10 = TRK_NR10
    ld l,a                          ; 7a3e 6f      
    ld a,[hl+]                      ; 7a3f 2a      
    ld c,$10                        ; 7a40 0e 10   
    ldh [c],a                       ; 7a42 e2      
    inc c                           ; 7a43 0c      
    jp KN_ChOutTail                 ; 7a44 c3 50 7a
KN_Ch2Out:
    call KN_ChanOwner               ; 7a47 cd 00 7a
    ld a,b                          ; 7a4a 78      
    add $08                         ; 7a4b c6 08     from TRK_NRX1
    ld l,a                          ; 7a4d 6f      
    ld c,$16                        ; 7a4e 0e 16   
KN_ChOutTail:
    ld a,[hl+]                      ; 7a50 2a        NRx1 = TRK_NRX1
    ldh [c],a                       ; 7a51 e2      
    inc c                           ; 7a52 0c      
    ld a,[hl+]                      ; 7a53 2a        NRx2 = TRK_NRX2
    ldh [c],a                       ; 7a54 e2      
    inc c                           ; 7a55 0c      
    ld a,[hl+]                      ; 7a56 2a        (TRK_NOTE + TRK_TRANSP) * 2, 8-bit
    add [hl]                        ; 7a57 86      
    sla a                           ; 7a58 cb 27   
    ld e,a                          ; 7a5a 5f      
    ld d,HIGH(KN_PeriodTable)       ; 7a5b 16 7f     KN_PeriodTable page
    ld a,[de]                       ; 7a5d 1a      
    inc e                           ; 7a5e 1c      
    ldh [c],a                       ; 7a5f e2        NRx3 = period low
    inc c                           ; 7a60 0c      
    ld a,[de]                       ; 7a61 1a      
    inc hl                          ; 7a62 23      
    or [hl]                         ; 7a63 b6        | TRK_NRX4
    or $80                          ; 7a64 f6 80     | trigger
    ldh [c],a                       ; 7a66 e2      
    ret                             ; 7a67 c9      
KN_Ch3Out:
    ld a,$80                        ; 7a68 3e 80     CH3 DAC on (every update, written or not)
    ldh [rNR30],a                   ; 7a6a e0 1a   
    call KN_ChanOwner               ; 7a6c cd 00 7a
    ld a,b                          ; 7a6f 78      
    add $08                         ; 7a70 c6 08   
    ld l,a                          ; 7a72 6f      
    ld c,$1c                        ; 7a73 0e 1c   
    ld a,[hl+]                      ; 7a75 2a      
    ldh [rNR31],a                   ; 7a76 e0 1b     NR31 = TRK_NRX1
    ld a,[hl+]                      ; 7a78 2a      
    ldh [rNR32],a                   ; 7a79 e0 1c     NR32 = TRK_NRX2 (level)
    ld a,[hl+]                      ; 7a7b 2a      
    add [hl]                        ; 7a7c 86      
    sla a                           ; 7a7d cb 27   
    ld e,a                          ; 7a7f 5f      
    ld d,HIGH(KN_PeriodTable)       ; 7a80 16 7f   
    ld a,[de]                       ; 7a82 1a      
    inc e                           ; 7a83 1c      
    ldh [rNR33],a                   ; 7a84 e0 1d   
    ld a,[de]                       ; 7a86 1a      
    or $c0                          ; 7a87 f6 c0     trigger + length enable, TRK_NRX4 ignored
    ldh [rNR34],a                   ; 7a89 e0 1e   
    ret                             ; 7a8b c9      
KN_Ch4Out:
    call KN_ChanOwner               ; 7a8c cd 00 7a
    ld a,b                          ; 7a8f 78      
    add $09                         ; 7a90 c6 09     from TRK_NRX2
    ld l,a                          ; 7a92 6f      
    ld c,$21                        ; 7a93 0e 21   
    ld a,[hl+]                      ; 7a95 2a      
    ldh [c],a                       ; 7a96 e2        NR42 = TRK_NRX2
    inc c                           ; 7a97 0c      
    ld a,[hl+]                      ; 7a98 2a      
    ldh [c],a                       ; 7a99 e2        NR43 = TRK_NOTE (the noise byte)
    inc c                           ; 7a9a 0c      
    ld a,$80                        ; 7a9b 3e 80   
    ldh [c],a                       ; 7a9d e2        NR44 = trigger
    ret                             ; 7a9e c9      

; KN_LoadRequest: hl = request byte, bc = first track of the set.
; 0 / $FF: nothing. Otherwise $FF is stored and four tracks start from KN_SoundTable.
KN_LoadRequest:
    ld a,[hl]                       ; 7a9f 7e        request id
    cp $00                          ; 7aa0 fe 00   
    jp z,KN_LoadRequest.done        ; 7aa2 ca d2 7a
    cp $ff                          ; 7aa5 fe ff   
    jp z,KN_LoadRequest.done        ; 7aa7 ca d2 7a
    ld d,$ff                        ; 7aaa 16 ff     mark the request taken
    ld [hl],d                       ; 7aac 72      
    sla a                           ; 7aad cb 27     id * 8 (8-bit: ids >= 32 wrap)
    sla a                           ; 7aaf cb 27   
    sla a                           ; 7ab1 cb 27   
    ld l,a                          ; 7ab3 6f      
    ld h,HIGH(KN_SoundTable)        ; 7ab4 26 7d     KN_SoundTable page
    ld e,$04                        ; 7ab6 1e 04   
.track
    ld a,$01                        ; 7ab8 3e 01     TRK_SPEED = 1 (track on)
    ld [bc],a                       ; 7aba 02      
    inc c                           ; 7abb 0c      
    dec a                           ; 7abc 3d      
    ld [bc],a                       ; 7abd 02        TRK_TICK = 0
    inc c                           ; 7abe 0c      
    ld a,[hl+]                      ; 7abf 2a        TRK_PTR = stream
    ld [bc],a                       ; 7ac0 02      
    inc c                           ; 7ac1 0c      
    ld a,[hl+]                      ; 7ac2 2a      
    ld [bc],a                       ; 7ac3 02      
    inc c                           ; 7ac4 0c      
    inc c                           ; 7ac5 0c      
    inc c                           ; 7ac6 0c      
    ld a,$00                        ; 7ac7 3e 00     TRK_INCALL = 0
    ld [bc],a                       ; 7ac9 02      
    ld a,c                          ; 7aca 79      
    add $0a                         ; 7acb c6 0a   
    ld c,a                          ; 7acd 4f      
    dec e                           ; 7ace 1d      
    jp nz,KN_LoadRequest.track      ; 7acf c2 b8 7a
.done
    ret                             ; 7ad2 c9      

; KN_NextTrack / KN_TrackStep: count a tick on track wCurTrack and read a row when
; TRK_TICK reaches TRK_SPEED: commands are run until a note ($00-$7F) or a hold ($89).
KN_NextTrack:
    ld a,[wCurTrack]                ; 7ad3 fa 90 c8  next track (+$10)
    add $10                         ; 7ad6 c6 10   
KN_TrackStep:
    ld [wCurTrack],a                ; 7ad8 ea 90 c8
    ld l,a                          ; 7adb 6f      
    ld h,HIGH(wSfxTracks)           ; 7adc 26 c8   
    ld a,[hl+]                      ; 7ade 2a      
    cp $00                          ; 7adf fe 00   
    jp z,KN_Cmd87_Stop.ret          ; 7ae1 ca 2b 7c  off
    inc [hl]                        ; 7ae4 34        TRK_TICK += 1
    ld d,[hl]                       ; 7ae5 56      
    cp d                            ; 7ae6 ba        == TRK_SPEED?
    jp nz,KN_Cmd87_Stop.ret         ; 7ae7 c2 2b 7c
    ld a,$00                        ; 7aea 3e 00     TRK_TICK = 0, read a row
    ld [hl+],a                      ; 7aec 22      
    ld c,[hl]                       ; 7aed 4e      
    inc l                           ; 7aee 2c      
    ld b,[hl]                       ; 7aef 46      
KN_ReadByte:
    ld a,[bc]                       ; 7af0 0a      
    inc bc                          ; 7af1 03      
    cp $80                          ; 7af2 fe 80     $00-$7F: note
    jp c,KN_StoreNote               ; 7af4 da 0d 7b
    cp $90                          ; 7af7 fe 90     $90-$FF: speed
    jp nc,KN_SetSpeed               ; 7af9 d2 23 7b
    and $0f                         ; 7afc e6 0f     $80-$8F: command
    sla a                           ; 7afe cb 27   
    ld e,a                          ; 7b00 5f      
    ld d,$00                        ; 7b01 16 00   
    ld hl,KN_CmdTable               ; 7b03 21 30 7b
    add hl,de                       ; 7b06 19      
    ld a,[hl+]                      ; 7b07 2a      
    ld h,[hl]                       ; 7b08 66      
    ld l,a                          ; 7b09 6f      
    jp hl                           ; 7b0a e9      
KN_Cmd89_Hold:
    ld a,$89                        ; 7b0b 3e 89     $89: hold, stored like a note
KN_StoreNote:
    ld e,a                          ; 7b0d 5f        TRK_NOTE
    ld a,[wCurTrack]                ; 7b0e fa 90 c8
    add $0a                         ; 7b11 c6 0a   
    ld l,a                          ; 7b13 6f      
    ld h,HIGH(wSfxTracks)           ; 7b14 26 c8   
    ld [hl],e                       ; 7b16 73      
    ld a,[wCurTrack]                ; 7b17 fa 90 c8
    add $02                         ; 7b1a c6 02   
    ld l,a                          ; 7b1c 6f      
    ld h,HIGH(wSfxTracks)           ; 7b1d 26 c8   
    ld [hl],c                       ; 7b1f 71        TRK_PTR = next byte
    inc l                           ; 7b20 2c      
    ld [hl],b                       ; 7b21 70      
    ret                             ; 7b22 c9      
KN_SetSpeed:
    sub $90                         ; 7b23 d6 90     TRK_SPEED = byte - $90
    ld e,a                          ; 7b25 5f      
    ld a,[wCurTrack]                ; 7b26 fa 90 c8
    ld l,a                          ; 7b29 6f      
    ld h,HIGH(wSfxTracks)           ; 7b2a 26 c8   
    ld [hl],e                       ; 7b2c 73      
    jp KN_ReadByte                  ; 7b2d c3 f0 7a

; KN_CmdTable: commands $80-$8F (low nibble)
KN_CmdTable:
    dw KN_Cmd80_NRx1, KN_Cmd81_NR10, KN_Cmd82_Transpose, KN_Cmd83_NRx2; 7b30  $80-$83
    dw KN_Cmd84_Skip, KN_Cmd85_Call, KN_Cmd86_Return, KN_Cmd87_Stop; 7b38  $84-$87
    dw KN_Cmd88_NRx4, KN_Cmd89_Hold, KN_Cmd8A_MusPan, KN_Cmd8B_Jump; 7b40  $88-$8B
    dw KN_Cmd8C_Wave, KN_Cmd84_Skip, KN_Cmd8E_NR50, KN_Cmd8F_SfxPan; 7b48  $8C-$8F

; Command handlers. bc = stream pointer (after the command byte).
KN_Cmd8F_SfxPan:
    ld a,[bc]                       ; 7b50 0a      
    inc bc                          ; 7b51 03      
    ld [wSfxPan],a                  ; 7b52 ea 1f c8
    jp KN_ReadByte                  ; 7b55 c3 f0 7a
KN_Cmd8A_MusPan:
    ld a,[bc]                       ; 7b58 0a      
    inc bc                          ; 7b59 03      
    ld [wMusPan],a                  ; 7b5a ea 0f c8
    jp KN_ReadByte                  ; 7b5d c3 f0 7a
KN_Cmd8E_NR50:
    ld a,[bc]                       ; 7b60 0a      
    inc bc                          ; 7b61 03      
    ldh [rNR50],a                   ; 7b62 e0 24   
    jp KN_ReadByte                  ; 7b64 c3 f0 7a
KN_Cmd8C_Wave:
    ld a,$00                        ; 7b67 3e 00     CH3 DAC off
    ldh [rNR30],a                   ; 7b69 e0 1a   
    ld h,HIGH(KN_WaveTable)         ; 7b6b 26 7e     KN_WaveTable page, the argument is the offset
    ld a,[bc]                       ; 7b6d 0a      
    inc bc                          ; 7b6e 03      
    ld l,a                          ; 7b6f 6f      
    ld de,$ff30                     ; 7b70 11 30 ff
    call KN_Copy4                   ; 7b73 cd 82 7b
    call KN_Copy4                   ; 7b76 cd 82 7b
    call KN_Copy4                   ; 7b79 cd 82 7b
    call KN_Copy4                   ; 7b7c cd 82 7b
    jp KN_ReadByte                  ; 7b7f c3 f0 7a
KN_Copy4:
    ld a,[hl+]                      ; 7b82 2a      
    ld [de],a                       ; 7b83 12      
    inc e                           ; 7b84 1c      
    ld a,[hl+]                      ; 7b85 2a      
    ld [de],a                       ; 7b86 12      
    inc e                           ; 7b87 1c      
    ld a,[hl+]                      ; 7b88 2a      
    ld [de],a                       ; 7b89 12      
    inc e                           ; 7b8a 1c      
    ld a,[hl+]                      ; 7b8b 2a      
    ld [de],a                       ; 7b8c 12      
    inc e                           ; 7b8d 1c      
    ret                             ; 7b8e c9      
KN_Cmd88_NRx4:
    ld a,[wCurTrack]                ; 7b8f fa 90 c8
    add $0c                         ; 7b92 c6 0c   
    jp KN_StoreArg                  ; 7b94 c3 b4 7b
KN_Cmd80_NRx1:
    ld a,[wCurTrack]                ; 7b97 fa 90 c8
    add $08                         ; 7b9a c6 08   
    jp KN_StoreArg                  ; 7b9c c3 b4 7b
KN_Cmd81_NR10:
    ld a,[wCurTrack]                ; 7b9f fa 90 c8
    add $07                         ; 7ba2 c6 07   
    jp KN_StoreArg                  ; 7ba4 c3 b4 7b
KN_Cmd82_Transpose:
    ld a,[wCurTrack]                ; 7ba7 fa 90 c8
    add $0b                         ; 7baa c6 0b   
    jp KN_StoreArg                  ; 7bac c3 b4 7b
KN_Cmd83_NRx2:
    ld a,[wCurTrack]                ; 7baf fa 90 c8
    add $09                         ; 7bb2 c6 09   
KN_StoreArg:
    ld l,a                          ; 7bb4 6f      
    ld h,HIGH(wSfxTracks)           ; 7bb5 26 c8   
    ld a,[bc]                       ; 7bb7 0a      
    inc bc                          ; 7bb8 03      
    ld [hl],a                       ; 7bb9 77      
    jp KN_ReadByte                  ; 7bba c3 f0 7a
KN_Cmd84_Skip:
    ld a,[bc]                       ; 7bbd 0a      
    inc bc                          ; 7bbe 03      
    jp KN_ReadByte                  ; 7bbf c3 f0 7a
KN_Cmd85_Call:
    ld a,[wCurTrack]                ; 7bc2 fa 90 c8  TRK_RET
    add $04                         ; 7bc5 c6 04   
    ld l,a                          ; 7bc7 6f      
    ld h,HIGH(wSfxTracks)           ; 7bc8 26 c8   
    ld a,[bc]                       ; 7bca 0a      
    inc bc                          ; 7bcb 03      
    ld e,a                          ; 7bcc 5f      
    ld a,[bc]                       ; 7bcd 0a      
    inc bc                          ; 7bce 03      
    ld [hl],c                       ; 7bcf 71      
    inc l                           ; 7bd0 2c      
    ld [hl],b                       ; 7bd1 70      
    inc l                           ; 7bd2 2c      
    ld b,a                          ; 7bd3 47      
    ld c,e                          ; 7bd4 4b      
    ld a,$01                        ; 7bd5 3e 01     TRK_INCALL = 1
    ld [hl],a                       ; 7bd7 77      
    jp KN_ReadByte                  ; 7bd8 c3 f0 7a
KN_Cmd86_Return:
    ld a,[wCurTrack]                ; 7bdb fa 90 c8  TRK_INCALL
    add $06                         ; 7bde c6 06   
    ld l,a                          ; 7be0 6f      
    ld h,HIGH(wSfxTracks)           ; 7be1 26 c8   
    ld a,[hl]                       ; 7be3 7e      
    cp $00                          ; 7be4 fe 00   
    jp z,KN_Cmd86_Return.endSet     ; 7be6 ca f2 7b
    ld a,$00                        ; 7be9 3e 00     clear it, back to TRK_RET
    ld [hl-],a                      ; 7beb 32      
    ld b,[hl]                       ; 7bec 46      
    dec l                           ; 7bed 2d      
    ld c,[hl]                       ; 7bee 4e      
    jp KN_ReadByte                  ; 7bef c3 f0 7a
.endSet
    ld b,$00                        ; 7bf2 06 00     not in a call: end the whole set
    ld a,[wCurSet]                  ; 7bf4 fa 91 c8  which set?
    cp $01                          ; 7bf7 fe 01   
    jp z,KN_Cmd86_Return.endMusic   ; 7bf9 ca 0f 7c
    ld hl,wSfxTracks                ; 7bfc 21 00 c8
    ld [hl],b                       ; 7bff 70      
    ld l,$10                        ; 7c00 2e 10   
    ld [hl],b                       ; 7c02 70      
    ld l,$20                        ; 7c03 2e 20   
    ld [hl],b                       ; 7c05 70      
    ld l,$30                        ; 7c06 2e 30   
    ld [hl],b                       ; 7c08 70      
    ld a,$00                        ; 7c09 3e 00     wSfxReq = 0
    ld [wSfxReq],a                  ; 7c0b ea 0e c8
    ret                             ; 7c0e c9      
.endMusic
    ld hl,wMusTracks                ; 7c0f 21 40 c8
    ld [hl],b                       ; 7c12 70      
    ld l,$50                        ; 7c13 2e 50   
    ld [hl],b                       ; 7c15 70      
    ld l,$60                        ; 7c16 2e 60   
    ld [hl],b                       ; 7c18 70      
    ld l,$70                        ; 7c19 2e 70   
    ld [hl],b                       ; 7c1b 70      
    ld a,$00                        ; 7c1c 3e 00     wMusReq = 0
    ld [wMusReq],a                  ; 7c1e ea 1e c8
    ret                             ; 7c21 c9      
KN_Cmd87_Stop:
    ld a,[wCurTrack]                ; 7c22 fa 90 c8  TRK_SPEED = 0 (this track only)
    ld l,a                          ; 7c25 6f      
    ld h,HIGH(wSfxTracks)           ; 7c26 26 c8   
    ld a,$00                        ; 7c28 3e 00   
    ld [hl],a                       ; 7c2a 77      
.ret
    ret                             ; 7c2b c9      
KN_Cmd8B_Jump:
    ld a,[bc]                       ; 7c2c 0a      
    inc bc                          ; 7c2d 03      
    ld l,a                          ; 7c2e 6f      
    ld a,[bc]                       ; 7c2f 0a      
    inc bc                          ; 7c30 03      
    ld b,a                          ; 7c31 47      
    ld c,l                          ; 7c32 4d      
    jp KN_ReadByte                  ; 7c33 c3 f0 7a
    ds $ca, $ff                    ; 7c36-7cff unused

; KN_SoundTable: 32 ids x 4 stream pointers (CH1, CH2, CH3, CH4).
; Ids 1, 2, $0D-$1F are SFX (wSfxReq); 3-$0C are songs (wMusReq); id 0 = all channels end at once.
KN_SoundTable:
    dw KN_Snd00_Ch1, KN_Snd00_Ch1, KN_Snd00_Ch1, KN_Snd00_Ch1; 7d00  id $00
    dw KN_Snd01_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch4; 7d08  id $01
    dw KN_Snd02_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd02_Ch4; 7d10  id $02
    dw KN_Snd03_Ch1, KN_Snd03_Ch2, KN_Snd03_Ch3, KN_Snd03_Ch4; 7d18  id $03
    dw KN_Snd04_Ch1, KN_Snd04_Ch2, KN_Snd04_Ch3, KN_Snd04_Ch4; 7d20  id $04
    dw KN_Snd05_Ch1, KN_Snd05_Ch2, KN_Snd05_Ch3, KN_Snd01_Ch2; 7d28  id $05
    dw KN_Snd06_Ch1, KN_Snd06_Ch2, KN_Snd06_Ch3, KN_Snd06_Ch4; 7d30  id $06
    dw KN_Snd07_Ch1, KN_Snd07_Ch2, KN_Snd07_Ch3, KN_Snd07_Ch4; 7d38  id $07
    dw KN_Snd08_Ch1, KN_Snd08_Ch2, KN_Snd08_Ch3, KN_Snd08_Ch4; 7d40  id $08
    dw KN_Snd09_Ch1, KN_Snd09_Ch2, KN_Snd09_Ch3, KN_Snd09_Ch4; 7d48  id $09
    dw KN_Snd0A_Ch1, KN_Snd0A_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7d50  id $0A
    dw KN_Snd0B_Ch1, KN_Snd0B_Ch2, KN_Snd0B_Ch3, KN_Snd0B_Ch4; 7d58  id $0B
    dw KN_Snd0C_Ch1, KN_Snd0C_Ch2, KN_Snd0C_Ch3, KN_Snd0C_Ch4; 7d60  id $0C
    dw KN_Snd0D_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7d68  id $0D
    dw KN_Snd0E_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7d70  id $0E
    dw KN_Snd0F_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7d78  id $0F
    dw KN_Snd10_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7d80  id $10
    dw KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd11_Ch4; 7d88  id $11
    dw KN_Snd12_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd12_Ch4; 7d90  id $12
    dw KN_Snd13_Ch1, KN_Snd13_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7d98  id $13
    dw KN_Snd14_Ch1, KN_Snd14_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7da0  id $14
    dw KN_Snd15_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7da8  id $15
    dw KN_Snd16_Ch1, KN_Snd16_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7db0  id $16
    dw KN_Snd17_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7db8  id $17
    dw KN_Snd18_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd18_Ch4; 7dc0  id $18
    dw KN_Snd19_Ch1, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2; 7dc8  id $19
    dw KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd1A_Ch4; 7dd0  id $1A
    dw KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd01_Ch2, KN_Snd1B_Ch4; 7dd8  id $1B
