; KN_WaveTable: CH3 waves, $8C xx copies 16 bytes from KN_WaveTable + xx
KN_WaveTable:
    db $00, $11, $22, $33, $44, $55, $66, $77, $88, $99, $aa, $bb, $cc, $dd, $ee, $ff; 7e00
    db $01, $23, $45, $67, $89, $ab, $cd, $ef, $fe, $dc, $ba, $98, $76, $54, $32, $10; 7e10
    db $00, $21, $42, $63, $84, $a5, $c6, $e7, $08, $29, $4a, $6b, $8c, $ad, $ce, $ef; 7e20
    db $04, $08, $0c, $0f, $0c, $08, $04, $00, $00, $00, $00, $00, $00, $00, $00, $00; 7e30
    db $02, $46, $8a, $ce, $ff, $ff, $ff, $ff, $ed, $cb, $a9, $87, $65, $43, $21, $00; 7e40

; KN_SndUpdate: the driver entry, called once per VBlank by the game (ROM0 $01AC,
; after rst $08 selected bank 1).
KN_SndUpdate:
    ld hl,wSfxReq                   ; 7e50 21 0e c8  SFX request
    ld bc,wSfxTracks                ; 7e53 01 00 c8
    call KN_LoadRequest             ; 7e56 cd 9f 7a
    ld hl,wMusReq                   ; 7e59 21 1e c8  music request
    ld bc,wMusTracks                ; 7e5c 01 40 c8
    call KN_LoadRequest             ; 7e5f cd 9f 7a
    ld a,$00                        ; 7e62 3e 00     wCurSet = 0 (SFX)
    ld [wCurSet],a                  ; 7e64 ea 91 c8
    call KN_TrackStep               ; 7e67 cd d8 7a  track $00 (a = 0)
    call KN_NextTrack               ; 7e6a cd d3 7a
    call KN_NextTrack               ; 7e6d cd d3 7a
    call KN_NextTrack               ; 7e70 cd d3 7a
    ld a,$01                        ; 7e73 3e 01     wCurSet = 1 (music)
    ld [wCurSet],a                  ; 7e75 ea 91 c8
    call KN_NextTrack               ; 7e78 cd d3 7a
    call KN_NextTrack               ; 7e7b cd d3 7a
    call KN_NextTrack               ; 7e7e cd d3 7a
    call KN_NextTrack               ; 7e81 cd d3 7a
    call KN_UpdatePan               ; 7e84 cd 9b 7e
    ld b,$00                        ; 7e87 06 00   
    call KN_Ch1Out                  ; 7e89 cd 36 7a
    ld b,$10                        ; 7e8c 06 10   
    call KN_Ch2Out                  ; 7e8e cd 47 7a
    ld b,$20                        ; 7e91 06 20   
    call KN_Ch3Out                  ; 7e93 cd 68 7a
    ld b,$30                        ; 7e96 06 30   
    jp KN_Ch4Out                    ; 7e98 c3 8c 7a

; KN_UpdatePan: NR51.
KN_UpdatePan:
    ld hl,wSfxTracks                ; 7e9b 21 00 c8  sum of the SFX TRK_SPEED bytes
    ld a,[hl]                       ; 7e9e 7e      
    ld l,$10                        ; 7e9f 2e 10   
    add [hl]                        ; 7ea1 86      
    ld l,$20                        ; 7ea2 2e 20   
    add [hl]                        ; 7ea4 86      
    ld l,$30                        ; 7ea5 2e 30   
    add [hl]                        ; 7ea7 86      
    cp $00                          ; 7ea8 fe 00   
    jp z,KN_UpdatePan.write         ; 7eaa ca b0 7e
    ld a,[wSfxPan]                  ; 7ead fa 1f c8  any SFX on: add wSfxPan
.write
    ld c,a                          ; 7eb0 4f      
    ld a,[wMusPan]                  ; 7eb1 fa 0f c8
    or c                            ; 7eb4 b1        NR51 = wMusPan | (SFX ? wSfxPan : 0)
    ldh [rNR51],a                   ; 7eb5 e0 25   
    ret                             ; 7eb7 c9      
    ds $48, $ff                    ; 7eb8-7eff unused

; KN_PeriodTable: 72 periods, C2 ... B7 (index = note + transpose)
KN_PeriodTable:
    dw $002c, $009d, $0107, $016b, $01c9, $0223, $0277, $02c7, $0312, $0358, $039b, $03da; 7f00
    dw $0416, $044e, $047f, $04b5, $04e5, $0511, $053b, $0563, $0589, $05ac, $05ce, $05ed; 7f18
    dw $060b, $0627, $0642, $065b, $0672, $0689, $069e, $06b2, $06c4, $06d6, $06e7, $06f7; 7f30
    dw $0706, $0714, $0721, $072d, $0739, $0744, $074f, $0759, $0762, $076b, $0773, $077b; 7f48
    dw $0783, $078a, $0790, $0797, $079d, $07a2, $07a7, $07ac, $07b1, $07b6, $07ba, $07be; 7f60
    dw $07c1, $07c5, $07c8, $07cb, $07ce, $07d1, $07d4, $07d6, $07d9, $07db, $07dd, $07df; 7f78
    ds $70, $ff                    ; 7f90-7fff unused
